  --color-text: #333333;
  --color-text-light: #666666;
  --color-bg: #ffffff;
  --color-bg-alt: #f4f4f4;
  --color-error: #d32f2f;
  --color-success: #388e3c;
  --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 4rem;
  --max-width: 1200px;
  --focus-ring: 3px solid #005fcc;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-main);
  color: var(--color-text);
  line-height: 1.6;
  background-color: var(--color-bg);
}

/* Focus Indicators */
:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

/* Skip Link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: #fff;
  padding: var(--spacing-xs) var(--spacing-sm);
  z-index: 1000;
  text-decoration: none;
  font-weight: bold;
}

.skip-link:focus {
  top: 0;
}

/* Layout */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-sm);
}

/* Header & Nav */
.site-header {
  background: var(--color-bg);
  border-bottom: 1px solid #ddd;
  padding: var(--spacing-sm) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--color-primary-dark);
  text-decoration: none;
}

.nav-toggle {
  display: none;
  background: none;
  border: 1px solid var(--color-text);
  padding: var(--spacing-xs);
  cursor: pointer;
}

.primary-nav ul {
  display: flex;
  list-style: none;
  gap: var(--spacing-sm);
}

.primary-nav a {
  text-decoration: none;
  color: var(--color-text);
  font-weight: 500;
  padding: var(--spacing-xs);
}

.primary-nav a:hover,
.primary-nav a:focus {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

/* Hero */
.hero {
  background-color: var(--color-secondary);
  padding: var(--spacing-lg) 0;
  text-align: center;
}

.hero h1 {
  font-size: 2.5rem;
  margin-bottom: var(--spacing-sm);
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-md);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.btn {
  display: inline-block;
  background: var(--color-primary);
  color: #fff;
  padding: var(--spacing-xs) var(--spacing-md);
  text-decoration: none;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 1rem;
}

.btn:hover {
  background: var(--color-primary-dark);
}

.btn:focus {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

/* Cards */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-md);
  padding: var(--spacing-md) 0;
}

.card {
  border: 1px solid #ddd;
  border-radius: 8px;
  overflow: hidden;
  background: #fff;
}

.card-img-placeholder {
  width: 100%;
  height: 200px;
  background: #e0e0e0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #666;
}

.card-body {
  padding: var(--spacing-sm);
}

.card-title {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-xs);
}

/* Forms */
.form-group {
  margin-bottom: var(--spacing-sm);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 500;
}

input, select, textarea {
  width: 100%;
  padding: var(--spacing-xs);
  border: 1px solid #ccc;
  border-radius: 4px;
  font-size: 1rem;
}

input:focus, select:focus, textarea:focus {
  border-color: var(--color-primary);
  outline: var(--focus-ring);
}

.error-message {
  color: var(--color-error);
  font-size: 0.875rem;
  margin-top: 4px;
}

.error-summary {
  background: #ffebee;
  border: 1px solid var(--color-error);
  padding: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
  border-radius: 4px;
}

.error-summary ul {
  margin-left: var(--spacing-md);
}

/* Footer */
.site-footer {
  background: var(--color-bg-alt);
  padding: var(--spacing-lg) 0;
  margin-top: var(--spacing-lg);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-md);
}

.footer-section h3 {
  margin-bottom: var(--spacing-sm);
}

.footer-section ul {
  list-style: none;
}

.footer-section a {
  color: var(--color-text-light);
  text-decoration: none;
}

.footer-section a:hover {
  text-decoration: underline;
}

/* Responsive */
@media (max-width: 768px) {
  .nav-toggle {
    display: block;
  }

  .primary-nav {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid #ddd;
    padding: var(--spacing-sm);
  }

  .primary-nav.is-open {
    display: block;
  }

  .primary-nav ul {
    flex-direction: column;
    gap: 0;
  }

  .primary-nav li {
    border-bottom: 1px solid #eee;
  }

  .primary-nav a {
    display: block;
    padding: var(--spacing-sm);
  }

  .hero h1 {
    font-size: 2rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}
